import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_06_td_update_loop.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_06_td_target_anatomy.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_06_td_error_signal.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_06_reward_propagation.png",d="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_06_mc_td_tradeoff.png",f=JSON.parse('{"title":"不用等到终点就能学习：时序差分为什么是强化学习的转折点","description":"蒙特卡洛方法要等完整回合结束，才能用真实回报更新价值。时序差分学习（Temporal-Difference Learning，时序差分学习）只需要观察一次状态转移，就能立刻修正刚刚离开的状态。它不要求完整环境模型，又像动态规划一样使用已有价值估计进行自举（Bootstrapping，自举），因此把“","frontmatter":{"title":"不用等到终点就能学习：时序差分为什么是强化学习的转折点","description":"蒙特卡洛方法要等完整回合结束，才能用真实回报更新价值。时序差分学习（Temporal-Difference Learning，时序差分学习）只需要观察一次状态转移，就能立刻修正刚刚离开的状态。它不要求完整环境模型，又像动态规划一样使用已有价值估计进行自举（Bootstrapping，自举），因此把“","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":19,"source":"2026-08-13/rl_series_06_temporal_difference.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_06_td_update_loop.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-06-temporal-difference"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"不用等到终点就能学习：时序差分为什么是强化学习的转折点"}],["meta",{"property":"og:description","content":"蒙特卡洛方法要等完整回合结束，才能用真实回报更新价值。时序差分学习（Temporal-Difference Learning，时序差分学习）只需要观察一次状态转移，就能立刻修正刚刚离开的状态。它不要求完整环境模型，又像动态规划一样使用已有价值估计进行自举（Bootstrapping，自举），因此把“"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-06-temporal-difference"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_06_td_update_loop.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"不用等到终点就能学习：时序差分为什么是强化学习的转折点"}],["meta",{"name":"twitter:description","content":"蒙特卡洛方法要等完整回合结束，才能用真实回报更新价值。时序差分学习（Temporal-Difference Learning，时序差分学习）只需要观察一次状态转移，就能立刻修正刚刚离开的状态。它不要求完整环境模型，又像动态规划一样使用已有价值估计进行自举（Bootstrapping，自举），因此把“"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_06_td_update_loop.png"}]],"prev":{"text":"不知道环境模型，也能学会决策？蒙特卡洛方法讲透了","link":"/rl/rl-series-05-monte-carlo"},"next":{"text":"为什么 Sarsa 会绕开悬崖？同策略学习真正“同”在哪里","link":"/rl/rl-series-07-sarsa"}},"headers":[],"relativePath":"rl/rl-series-06-temporal-difference.md","filePath":"rl/rl-series-06-temporal-difference.md","lastUpdated":null}'),s={name:"rl/rl-series-06-temporal-difference.md"};function p(_,a,c,u,b,q){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="不用等到终点就能学习-时序差分为什么是强化学习的转折点" tabindex="-1">不用等到终点就能学习：时序差分为什么是强化学习的转折点 <a class="header-anchor" href="#不用等到终点就能学习-时序差分为什么是强化学习的转折点" aria-label="Permalink to &quot;不用等到终点就能学习：时序差分为什么是强化学习的转折点&quot;">​</a></h1><p>蒙特卡洛方法要等完整回合结束，才能用真实回报更新价值。时序差分学习（Temporal-Difference Learning，时序差分学习）只需要观察一次状态转移，就能立刻修正刚刚离开的状态。它不要求完整环境模型，又像动态规划一样使用已有价值估计进行自举（Bootstrapping，自举），因此把“从经验学习”和“逐步传播价值”真正接到了一起。</p><p>最简单的 TD(0) 只有一条更新公式，却藏着强化学习最重要的结构：采样、时序差分目标、时序差分误差、学习率和自举。Sarsa、Q-learning（Q 学习）、Deep Q-Network（深度 Q 网络）乃至 Actor-Critic（演员—评论家）方法，都能在这条结构上找到自己的影子。</p><p>本文先讨论固定策略下的价值预测，不急着寻找最优动作。把 TD(0) 的目标、误差和边界弄清楚，下一篇进入 Sarsa 控制时，才不会把“更新哪个值”“下一动作从哪里来”和“正在评估谁的策略”混在一起。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-td-是蒙特卡洛采样与动态规划自举的结合" tabindex="-1">1.1 TD 是蒙特卡洛采样与动态规划自举的结合 <a class="header-anchor" href="#_1-1-td-是蒙特卡洛采样与动态规划自举的结合" aria-label="Permalink to &quot;1.1 TD 是蒙特卡洛采样与动态规划自举的结合&quot;">​</a></h3><p>TD 和蒙特卡洛一样，直接使用与环境交互得到的样本，不要求显式状态转移概率。TD 又和动态规划一样，用后继状态的当前价值估计帮助更新当前状态。它既不是缩短版蒙特卡洛，也不是缺少模型的动态规划，而是一类独立的增量学习方法。</p><h3 id="_1-2-td-0-每观察一步就能更新一次" tabindex="-1">1.2 TD(0) 每观察一步就能更新一次 <a class="header-anchor" href="#_1-2-td-0-每观察一步就能更新一次" aria-label="Permalink to &quot;1.2 TD(0) 每观察一步就能更新一次&quot;">​</a></h3><p>从 (S_t) 执行动作后，环境返回奖励 (R_{t+1}) 和下一状态 (S_{t+1})。此时不需要知道回合最终结局，就能用 (R_{t+1}+\\gamma V(S_{t+1})) 构造目标并更新 (V(S_t))。这让 TD 可以处理很长的回合，甚至在定义良好的持续式任务中持续学习。</p><h3 id="_1-3-速度来自自举-代价也来自自举" tabindex="-1">1.3 速度来自自举，代价也来自自举 <a class="header-anchor" href="#_1-3-速度来自自举-代价也来自自举" aria-label="Permalink to &quot;1.3 速度来自自举，代价也来自自举&quot;">​</a></h3><p>TD 目标包含 (V(S_{t+1}))，所以能借用后继状态已经学到的信息，通常比等待完整回报更快、方差更低。但后继价值本身可能不准确，误差也会沿状态链传播。初始化、学习率、状态表示和数据分布都会影响学习过程。</p><h3 id="_1-4-每步更新不等于奖励立刻传到所有状态" tabindex="-1">1.4 每步更新不等于奖励立刻传到所有状态 <a class="header-anchor" href="#_1-4-每步更新不等于奖励立刻传到所有状态" aria-label="Permalink to &quot;1.4 每步更新不等于奖励立刻传到所有状态&quot;">​</a></h3><p>若奖励只在终点出现，TD(0) 会先修正终点附近的状态，再通过后续访问逐步向前传播。它可以在每一步更新，却仍可能需要多个回合才能把稀疏奖励传到很早的决策位置。在线更新解决的是等待方式，不会自动消除长时信用分配问题。</p><p><img src="'+o+'" alt="时序差分学习每观察一次状态转移就更新一次价值"></p><h2 id="二、从蒙特卡洛走到-td-只改了学习目标" tabindex="-1">二、从蒙特卡洛走到 TD，只改了学习目标 <a class="header-anchor" href="#二、从蒙特卡洛走到-td-只改了学习目标" aria-label="Permalink to &quot;二、从蒙特卡洛走到 TD，只改了学习目标&quot;">​</a></h2><h3 id="_2-1-蒙特卡洛把完整回报当目标" tabindex="-1">2.1 蒙特卡洛把完整回报当目标 <a class="header-anchor" href="#_2-1-蒙特卡洛把完整回报当目标" aria-label="Permalink to &quot;2.1 蒙特卡洛把完整回报当目标&quot;">​</a></h3><p>固定策略 (\\pi) 下，蒙特卡洛更新可以写成：</p><p>$$ V(S_t)\\leftarrow V(S_t)+\\alpha\\left[G_t-V(S_t)\\right] $$</p><p>其中 (G_t) 包含从时刻 (t) 到回合终点的全部折扣奖励。只有回合结束后，(G_t) 才完整可知。</p><h3 id="_2-2-td-把单步奖励与后继估计拼成目标" tabindex="-1">2.2 TD 把单步奖励与后继估计拼成目标 <a class="header-anchor" href="#_2-2-td-把单步奖励与后继估计拼成目标" aria-label="Permalink to &quot;2.2 TD 把单步奖励与后继估计拼成目标&quot;">​</a></h3><p>TD(0) 的更新是：</p><p>$$ V(S_t)\\leftarrow V(S_t)+\\alpha\\left[R_{t+1}+\\gamma V(S_{t+1})-V(S_t)\\right] $$</p><p>它只等待一次转移。(R_{t+1}) 是刚刚观察到的真实样本，(V(S_{t+1})) 是当前学习系统对后续未来的估计。两者相加，形成一步前瞻的学习目标。</p><h3 id="_2-3-变化虽小-数据流已经完全不同" tabindex="-1">2.3 变化虽小，数据流已经完全不同 <a class="header-anchor" href="#_2-3-变化虽小-数据流已经完全不同" aria-label="Permalink to &quot;2.3 变化虽小，数据流已经完全不同&quot;">​</a></h3><p>蒙特卡洛需要保存或回看整段轨迹，然后从终点向前计算回报。TD(0) 可以在环境返回一步结果后立即更新，再进入下一次交互。它的存储需求通常更小，也不依赖自然回合结束才能产生训练信号。</p><h2 id="三、把-td-0-公式拆成五个零件" tabindex="-1">三、把 TD(0) 公式拆成五个零件 <a class="header-anchor" href="#三、把-td-0-公式拆成五个零件" aria-label="Permalink to &quot;三、把 TD(0) 公式拆成五个零件&quot;">​</a></h2><h3 id="_3-1-当前估计是被修正对象" tabindex="-1">3.1 当前估计是被修正对象 <a class="header-anchor" href="#_3-1-当前估计是被修正对象" aria-label="Permalink to &quot;3.1 当前估计是被修正对象&quot;">​</a></h3><p>(V(S_t)) 表示系统此刻对状态 (S_t) 的价值预测。更新不是把旧值全部丢掉，而是沿误差方向移动一小段。</p><h3 id="_3-2-单步奖励来自真实交互" tabindex="-1">3.2 单步奖励来自真实交互 <a class="header-anchor" href="#_3-2-单步奖励来自真实交互" aria-label="Permalink to &quot;3.2 单步奖励来自真实交互&quot;">​</a></h3><p>(R_{t+1}) 是执行动作后的观测结果。奖励为零不表示这次转移没有学习信息，因为下一状态价值仍可能改变当前状态的目标。</p><h3 id="_3-3-后继价值负责代表尚未发生的未来" tabindex="-1">3.3 后继价值负责代表尚未发生的未来 <a class="header-anchor" href="#_3-3-后继价值负责代表尚未发生的未来" aria-label="Permalink to &quot;3.3 后继价值负责代表尚未发生的未来&quot;">​</a></h3><p>(V(S_{t+1})) 把时刻 (t+1) 之后的长期收益压缩成一个估计。TD 不用等未来全部发生，就先借用这个估计。这里正是自举发生的位置。</p><h3 id="_3-4-折扣因子控制未来信息权重" tabindex="-1">3.4 折扣因子控制未来信息权重 <a class="header-anchor" href="#_3-4-折扣因子控制未来信息权重" aria-label="Permalink to &quot;3.4 折扣因子控制未来信息权重&quot;">​</a></h3><p>(\\gamma) 越接近零，更新越依赖即时奖励；越接近一，后继价值影响越大。它不是单纯的“耐心参数”，还参与定义任务回报，并影响误差传播和数值尺度。</p><h3 id="_3-5-学习率控制一次修正幅度" tabindex="-1">3.5 学习率控制一次修正幅度 <a class="header-anchor" href="#_3-5-学习率控制一次修正幅度" aria-label="Permalink to &quot;3.5 学习率控制一次修正幅度&quot;">​</a></h3><p>(\\alpha) 决定本次误差写入价值表的比例。(\\alpha) 太大可能持续振荡，太小则学习缓慢。固定学习率适合跟踪变化，但会保留长期波动；递减学习率更接近稳定估计，却降低后期适应速度。</p><p><img src="'+l+'" alt="TD 目标、当前估计与学习率在一次更新中的关系"></p><h2 id="四、时序差分目标究竟估计了什么" tabindex="-1">四、时序差分目标究竟估计了什么 <a class="header-anchor" href="#四、时序差分目标究竟估计了什么" aria-label="Permalink to &quot;四、时序差分目标究竟估计了什么&quot;">​</a></h2><h3 id="_4-1-目标由样本和估计共同组成" tabindex="-1">4.1 目标由样本和估计共同组成 <a class="header-anchor" href="#_4-1-目标由样本和估计共同组成" aria-label="Permalink to &quot;4.1 目标由样本和估计共同组成&quot;">​</a></h3><p>时序差分目标（TD Target，时序差分目标）定义为：</p><p>$$ Y_t^{TD}=R_{t+1}+\\gamma V(S_{t+1}) $$</p><p>它包含两层近似。环境中可能有多种下一状态和奖励，当前只采样到其中一种；真实的 (v_\\pi(S_{t+1})) 也未知，当前只能使用 (V(S_{t+1}))。因此 TD 同时承担采样噪声和价值估计误差。</p><h3 id="_4-2-目标不是实际完整回报" tabindex="-1">4.2 目标不是实际完整回报 <a class="header-anchor" href="#_4-2-目标不是实际完整回报" aria-label="Permalink to &quot;4.2 目标不是实际完整回报&quot;">​</a></h3><p>如果从下一时刻开始发生意外，实际 (G_t) 可能与当前 TD 目标差很多。TD 并没有预知未来，只是根据“刚看到的一步”和“目前对后续的判断”形成可立即使用的估计。</p><h3 id="_4-3-正确固定点不等于每个目标都正确" tabindex="-1">4.3 正确固定点不等于每个目标都正确 <a class="header-anchor" href="#_4-3-正确固定点不等于每个目标都正确" aria-label="Permalink to &quot;4.3 正确固定点不等于每个目标都正确&quot;">​</a></h3><p>表格型、固定策略、充分访问并采用合适学习率时，TD(0) 可以收敛到 (v_\\pi)。但训练早期的单个目标仍可能明显偏离真实价值。算法依靠大量更新让局部估计相互协调，不是因为每次目标都天然准确。</p><h2 id="五、时序差分误差不是奖励" tabindex="-1">五、时序差分误差不是奖励 <a class="header-anchor" href="#五、时序差分误差不是奖励" aria-label="Permalink to &quot;五、时序差分误差不是奖励&quot;">​</a></h2><h3 id="_5-1-td-误差衡量相邻预测是否一致" tabindex="-1">5.1 TD 误差衡量相邻预测是否一致 <a class="header-anchor" href="#_5-1-td-误差衡量相邻预测是否一致" aria-label="Permalink to &quot;5.1 TD 误差衡量相邻预测是否一致&quot;">​</a></h3><p>时序差分误差（TD Error，时序差分误差）是：</p><p>$$ \\delta_t=R_{t+1}+\\gamma V(S_{t+1})-V(S_t) $$</p><p>它比较“旧预测 (V(S_t))”与“新的一步目标”。(\\delta_t&gt;0) 表示刚观察到的转移比原先预期更好，(\\delta_t&lt;0) 表示结果比预期更差。</p><h3 id="_5-2-正奖励也可能对应负误差" tabindex="-1">5.2 正奖励也可能对应负误差 <a class="header-anchor" href="#_5-2-正奖励也可能对应负误差" aria-label="Permalink to &quot;5.2 正奖励也可能对应负误差&quot;">​</a></h3><p>假设收到正奖励，但 (V(S_t)) 原本高得不合理，而后继状态价值较低，(\\delta_t) 仍可能为负。反过来，即时奖励为零，只要下一状态价值显著高于当前预测，误差也可以为正。</p><p>所以 TD 误差不能被解释成奖励的别名。奖励来自环境定义，TD 误差来自奖励和两个价值预测之间的关系，是学习系统内部的预测残差。</p><h3 id="_5-3-更新就是把误差写回当前状态" tabindex="-1">5.3 更新就是把误差写回当前状态 <a class="header-anchor" href="#_5-3-更新就是把误差写回当前状态" aria-label="Permalink to &quot;5.3 更新就是把误差写回当前状态&quot;">​</a></h3><p>有了 (\\delta_t)，公式可以简写为：</p><p>$$ V(S_t)\\leftarrow V(S_t)+\\alpha\\delta_t $$</p><p>误差只直接修改当前状态。其他状态要在自己的转移被访问时获得更新，或者通过多步回报、资格迹等机制更快接收信号。</p><p><img src="'+h+'" alt="相邻价值预测不一致时产生时序差分误差"></p><h2 id="六、自举为什么能让价值逐步传播" tabindex="-1">六、自举为什么能让价值逐步传播 <a class="header-anchor" href="#六、自举为什么能让价值逐步传播" aria-label="Permalink to &quot;六、自举为什么能让价值逐步传播&quot;">​</a></h2><h3 id="_6-1-后继状态先学到-前驱状态随后受益" tabindex="-1">6.1 后继状态先学到，前驱状态随后受益 <a class="header-anchor" href="#_6-1-后继状态先学到-前驱状态随后受益" aria-label="Permalink to &quot;6.1 后继状态先学到，前驱状态随后受益&quot;">​</a></h3><p>考虑一条状态链，奖励只在终点出现。终点附近状态先通过终止奖励得到修正。后续回合再次访问前一个状态时，它看到后继状态价值已经升高，于是自己的 TD 目标也升高。多次交互后，价值沿相邻状态逐段向前传播。</p><h3 id="_6-2-每步更新与传播距离是两件事" tabindex="-1">6.2 每步更新与传播距离是两件事 <a class="header-anchor" href="#_6-2-每步更新与传播距离是两件事" aria-label="Permalink to &quot;6.2 每步更新与传播距离是两件事&quot;">​</a></h3><p>TD(0) 的确每步都更新，但一次更新只前瞻一个转移。按照标准在线顺序，刚在回合尾部产生的奖励不会瞬间改写回合开头所有状态。回合越长、奖励越稀疏，传播到早期状态所需的重复访问越多。</p><h3 id="_6-3-多步方法在两端之间搭桥" tabindex="-1">6.3 多步方法在两端之间搭桥 <a class="header-anchor" href="#_6-3-多步方法在两端之间搭桥" aria-label="Permalink to &quot;6.3 多步方法在两端之间搭桥&quot;">​</a></h3><p>若目标使用未来 (n) 个真实奖励，再接上第 (n) 步后的价值估计，就得到 (n)-step TD（(n) 步时序差分）。(n=1) 对应 TD(0) 的一步目标；(n) 延伸到回合剩余长度时接近蒙特卡洛回报。TD((\\lambda)) 则把不同步长的回报按权重组合起来。</p><p>本文只把多步方法作为坐标，不展开算法实现。它们提醒我们：蒙特卡洛与 TD 不是互斥阵营，而是由“看多远再自举”连接起来的一条连续谱。</p><p><img src="'+n+'" alt="稀疏终点奖励通过自举沿状态链逐步向前传播"></p><h2 id="七、td-为什么能够在线学习" tabindex="-1">七、TD 为什么能够在线学习 <a class="header-anchor" href="#七、td-为什么能够在线学习" aria-label="Permalink to &quot;七、TD 为什么能够在线学习&quot;">​</a></h2><h3 id="_7-1-一次转移已经足够形成目标" tabindex="-1">7.1 一次转移已经足够形成目标 <a class="header-anchor" href="#_7-1-一次转移已经足够形成目标" aria-label="Permalink to &quot;7.1 一次转移已经足够形成目标&quot;">​</a></h3><p>TD 更新需要的最小数据是 ((S_t,R_{t+1},S_{t+1}))。在固定策略预测中，动作由策略决定，价值更新本身不必保存整条回合。数据到达一步，学习就可以前进一步。</p><h3 id="_7-2-在线指更新时机-不代表直接上真实系统" tabindex="-1">7.2 在线指更新时机，不代表直接上真实系统 <a class="header-anchor" href="#_7-2-在线指更新时机-不代表直接上真实系统" aria-label="Permalink to &quot;7.2 在线指更新时机，不代表直接上真实系统&quot;">​</a></h3><p>在线学习（Online Learning，在线学习）在这里指数据按时间到达并被增量处理。它不表示算法已经满足实时计算预算、功能安全、故障诊断或道路测试要求，更不表示允许车辆在真实交通中边犯错边学习。</p><h3 id="_7-3-持续式任务仍需明确回报定义" tabindex="-1">7.3 持续式任务仍需明确回报定义 <a class="header-anchor" href="#_7-3-持续式任务仍需明确回报定义" aria-label="Permalink to &quot;7.3 持续式任务仍需明确回报定义&quot;">​</a></h3><p>TD 不必等终点，所以可以用于持续式任务。但价值依然需要合理定义，例如使用 (\\gamma&lt;1) 的折扣回报，或采用平均奖励框架。没有终点并不等于可以忽略数值发散、时间尺度与策略稳定性。</p><h2 id="八、td-与蒙特卡洛的偏差—方差取舍" tabindex="-1">八、TD 与蒙特卡洛的偏差—方差取舍 <a class="header-anchor" href="#八、td-与蒙特卡洛的偏差—方差取舍" aria-label="Permalink to &quot;八、TD 与蒙特卡洛的偏差—方差取舍&quot;">​</a></h2><h3 id="_8-1-蒙特卡洛目标通常方差较高" tabindex="-1">8.1 蒙特卡洛目标通常方差较高 <a class="header-anchor" href="#_8-1-蒙特卡洛目标通常方差较高" aria-label="Permalink to &quot;8.1 蒙特卡洛目标通常方差较高&quot;">​</a></h3><p>完整回报 (G_t) 汇集了后续所有环境随机性和动作随机性。越靠近回合开头，随机因素累积越多。它在固定策略和正确回合语义下可以作为真实价值的无偏样本，但有限样本波动可能很大。</p><h3 id="_8-2-td-目标通常方差更低但带有估计偏差" tabindex="-1">8.2 TD 目标通常方差更低但带有估计偏差 <a class="header-anchor" href="#_8-2-td-目标通常方差更低但带有估计偏差" aria-label="Permalink to &quot;8.2 TD 目标通常方差更低但带有估计偏差&quot;">​</a></h3><p>一步 TD 只采样一次奖励和下一状态，没有把整条未来的随机奖励都装进单个目标，因此方差通常更低。代价是使用尚未收敛的 (V(S_{t+1}))，训练过程中目标会受到当前估计偏差影响。</p><h3 id="_8-3-通常-不能被写成绝对排名" tabindex="-1">8.3 “通常”不能被写成绝对排名 <a class="header-anchor" href="#_8-3-通常-不能被写成绝对排名" aria-label="Permalink to &quot;8.3 “通常”不能被写成绝对排名&quot;">​</a></h3><p>TD 并不在所有任务、学习率和样本预算下都优于蒙特卡洛。状态表示不满足马尔可夫性、学习率不合适、初始化很差或函数逼近不稳定时，TD 可能表现更差。方法比较必须固定数据预算、评价指标、随机种子和超参数搜索规则。</p><p><img src="'+d+'" alt="蒙特卡洛与 TD 在目标长度、偏差、方差和更新时机上的取舍"></p><h2 id="九、一个-开车回家-的直觉例子" tabindex="-1">九、一个“开车回家”的直觉例子 <a class="header-anchor" href="#九、一个-开车回家-的直觉例子" aria-label="Permalink to &quot;九、一个“开车回家”的直觉例子&quot;">​</a></h2><h3 id="_9-1-蒙特卡洛要等真正到家" tabindex="-1">9.1 蒙特卡洛要等真正到家 <a class="header-anchor" href="#_9-1-蒙特卡洛要等真正到家" aria-label="Permalink to &quot;9.1 蒙特卡洛要等真正到家&quot;">​</a></h3><p>出发时预计半小时到家，途中遭遇拥堵，最终花了更长时间。蒙特卡洛要等行程结束，才能知道从每个位置出发的实际剩余时间，并据此修正此前预测。</p><h3 id="_9-2-td-在拥堵发生时已经发现不一致" tabindex="-1">9.2 TD 在拥堵发生时已经发现不一致 <a class="header-anchor" href="#_9-2-td-在拥堵发生时已经发现不一致" aria-label="Permalink to &quot;9.2 TD 在拥堵发生时已经发现不一致&quot;">​</a></h3><p>车辆进入拥堵路段后，对“当前位置到家还要多久”的估计突然增大。即使尚未到家，也已经知道出发时的总时间预测过于乐观。TD 会立即把出发状态的预测朝“已耗时间加当前剩余时间估计”方向修正。</p><h3 id="_9-3-学到的是相邻预测关系" tabindex="-1">9.3 学到的是相邻预测关系 <a class="header-anchor" href="#_9-3-学到的是相邻预测关系" aria-label="Permalink to &quot;9.3 学到的是相邻预测关系&quot;">​</a></h3><p>TD 不需要这趟行程的最终答案才开始学习，它不断比较相邻时刻的预测。若每段经历都能让前后预测更一致，长期就能逼近固定驾驶策略下的期望到达时间。</p><h2 id="十、终止与截断在-td-中怎样处理" tabindex="-1">十、终止与截断在 TD 中怎样处理 <a class="header-anchor" href="#十、终止与截断在-td-中怎样处理" aria-label="Permalink to &quot;十、终止与截断在 TD 中怎样处理&quot;">​</a></h2><h3 id="_10-1-自然终止状态的后继价值为零" tabindex="-1">10.1 自然终止状态的后继价值为零 <a class="header-anchor" href="#_10-1-自然终止状态的后继价值为零" aria-label="Permalink to &quot;10.1 自然终止状态的后继价值为零&quot;">​</a></h3><p>如果 (S_{t+1}) 是任务真正的终止状态，未来不再产生奖励，通常定义 (V(S_{t+1})=0)。此时目标退化为 (R_{t+1})，终点奖励直接修正终点前状态。</p><h3 id="_10-2-时间上限截断未必意味着未来为零" tabindex="-1">10.2 时间上限截断未必意味着未来为零 <a class="header-anchor" href="#_10-2-时间上限截断未必意味着未来为零" aria-label="Permalink to &quot;10.2 时间上限截断未必意味着未来为零&quot;">​</a></h3><p>训练框架因为最大步数停止回合，并不代表任务本身结束。若底层任务仍会继续，截断处通常应保留后继价值自举。把所有截断都当成终止，会系统性低估靠近时间边界的状态价值。</p><h3 id="_10-3-接口字段必须进入算法语义" tabindex="-1">10.3 接口字段必须进入算法语义 <a class="header-anchor" href="#_10-3-接口字段必须进入算法语义" aria-label="Permalink to &quot;10.3 接口字段必须进入算法语义&quot;">​</a></h3><p>环境返回的 terminated（自然终止）和 truncated（截断）不是日志装饰。目标计算必须明确何时屏蔽 (\\gamma V(S_{t+1}))，实验记录也要写清回合边界、超时规则和尾部价值处理。</p><h2 id="十一、学习率、初始化与奖励尺度如何影响结果" tabindex="-1">十一、学习率、初始化与奖励尺度如何影响结果 <a class="header-anchor" href="#十一、学习率、初始化与奖励尺度如何影响结果" aria-label="Permalink to &quot;十一、学习率、初始化与奖励尺度如何影响结果&quot;">​</a></h2><h3 id="_11-1-学习率决定稳定与响应之间的平衡" tabindex="-1">11.1 学习率决定稳定与响应之间的平衡 <a class="header-anchor" href="#_11-1-学习率决定稳定与响应之间的平衡" aria-label="Permalink to &quot;11.1 学习率决定稳定与响应之间的平衡&quot;">​</a></h3><p>固定 (\\alpha) 对近期变化响应快，但估计会持续波动。满足适当递减条件的学习率有利于表格型固定策略估计收敛，却可能难以跟踪环境变化。工程中不能只写“使用 0.1”，还要报告访问频率、训练长度和敏感性分析。</p><h3 id="_11-2-初始化会通过自举向周围传播" tabindex="-1">11.2 初始化会通过自举向周围传播 <a class="header-anchor" href="#_11-2-初始化会通过自举向周围传播" aria-label="Permalink to &quot;11.2 初始化会通过自举向周围传播&quot;">​</a></h3><p>如果所有非终止状态都初始化为很高的价值，TD 目标会暂时继承这种乐观；初始化过低也会产生相反影响。表格型充分采样时影响可以逐渐消退，但有限训练和策略控制会让初始化改变探索路径与早期表现。</p><h3 id="_11-3-奖励尺度改变误差和有效步长" tabindex="-1">11.3 奖励尺度改变误差和有效步长 <a class="header-anchor" href="#_11-3-奖励尺度改变误差和有效步长" aria-label="Permalink to &quot;11.3 奖励尺度改变误差和有效步长&quot;">​</a></h3><p>奖励整体放大，TD 误差也会放大。同一个 (\\alpha) 在不同奖励尺度下并不具有相同效果。修改奖励后必须重新检查价值范围、梯度或更新幅度，不能机械复用原超参数。</p><h2 id="十二、状态不满足马尔可夫性时会发生什么" tabindex="-1">十二、状态不满足马尔可夫性时会发生什么 <a class="header-anchor" href="#十二、状态不满足马尔可夫性时会发生什么" aria-label="Permalink to &quot;十二、状态不满足马尔可夫性时会发生什么&quot;">​</a></h2><h3 id="_12-1-相同观测可能隐藏不同未来" tabindex="-1">12.1 相同观测可能隐藏不同未来 <a class="header-anchor" href="#_12-1-相同观测可能隐藏不同未来" aria-label="Permalink to &quot;12.1 相同观测可能隐藏不同未来&quot;">​</a></h3><p>若观测没有包含速度、加速度、交通灯阶段或必要历史，两个外观相同的输入可能对应完全不同的下一状态分布。TD 会把它们压进同一个 (V) 值，误差看似反复振荡，根因却可能是状态混叠，而不是学习率。</p><h3 id="_12-2-自举会传播表示误差" tabindex="-1">12.2 自举会传播表示误差 <a class="header-anchor" href="#_12-2-自举会传播表示误差" aria-label="Permalink to &quot;12.2 自举会传播表示误差&quot;">​</a></h3><p>后继状态价值不准确时，当前目标也被污染。状态别名、感知噪声和分布漂移会通过自举沿数据链传播。增加训练步数不能保证修复缺失信息，可能只让错误固定点估计得更稳定。</p><h3 id="_12-3-历史状态或信念状态是建模方案" tabindex="-1">12.3 历史状态或信念状态是建模方案 <a class="header-anchor" href="#_12-3-历史状态或信念状态是建模方案" aria-label="Permalink to &quot;12.3 历史状态或信念状态是建模方案&quot;">​</a></h3><p>可以加入有限历史、递归表示或信念状态，让输入更接近决策所需的充分信息。但这会增加状态空间和训练难度。是否需要历史应通过可观测性分析和对照实验判断，而不是默认网络会自动恢复所有隐藏变量。</p><h2 id="十三、表格型收敛结论不能怎样外推" tabindex="-1">十三、表格型收敛结论不能怎样外推 <a class="header-anchor" href="#十三、表格型收敛结论不能怎样外推" aria-label="Permalink to &quot;十三、表格型收敛结论不能怎样外推&quot;">​</a></h2><h3 id="_13-1-固定策略与充分访问是重要条件" tabindex="-1">13.1 固定策略与充分访问是重要条件 <a class="header-anchor" href="#_13-1-固定策略与充分访问是重要条件" aria-label="Permalink to &quot;13.1 固定策略与充分访问是重要条件&quot;">​</a></h3><p>经典 TD(0) 预测先假设策略固定，每个相关状态持续被访问，并采用满足条件的学习率。若策略同时快速变化，数据分布也在变化，价值目标不再静止。</p><h3 id="_13-2-函数逼近改变更新耦合" tabindex="-1">13.2 函数逼近改变更新耦合 <a class="header-anchor" href="#_13-2-函数逼近改变更新耦合" aria-label="Permalink to &quot;13.2 函数逼近改变更新耦合&quot;">​</a></h3><p>表格中修改一个状态值，不会直接改变其他状态。Function Approximation（函数逼近）用共享参数表示许多状态，更新一个样本可能同时改变大范围预测。泛化提高了可扩展性，也带来干扰和稳定性问题。</p><h3 id="_13-3-致命三角必须提前认识" tabindex="-1">13.3 致命三角必须提前认识 <a class="header-anchor" href="#_13-3-致命三角必须提前认识" aria-label="Permalink to &quot;13.3 致命三角必须提前认识&quot;">​</a></h3><p>Deadly Triad（致命三角）指函数逼近、自举和异策略学习组合时可能出现的不稳定甚至发散。它不表示三者任何一个单独使用都错误，而是提醒我们：从表格 TD(0) 走向深度异策略算法后，不能继续照搬简单收敛直觉。</p><h2 id="十四、td-预测怎样走向控制" tabindex="-1">十四、TD 预测怎样走向控制 <a class="header-anchor" href="#十四、td-预测怎样走向控制" aria-label="Permalink to &quot;十四、TD 预测怎样走向控制&quot;">​</a></h2><h3 id="_14-1-状态价值预测先回答-当前策略多好" tabindex="-1">14.1 状态价值预测先回答“当前策略多好” <a class="header-anchor" href="#_14-1-状态价值预测先回答-当前策略多好" aria-label="Permalink to &quot;14.1 状态价值预测先回答“当前策略多好”&quot;">​</a></h3><p>本文的 (V(S_t)) 更新默认轨迹由固定策略 (\\pi) 产生。它评估策略，不负责直接比较动作。只有预测准确，也不会自动产生更优策略。</p><h3 id="_14-2-控制需要改为学习动作价值" tabindex="-1">14.2 控制需要改为学习动作价值 <a class="header-anchor" href="#_14-2-控制需要改为学习动作价值" aria-label="Permalink to &quot;14.2 控制需要改为学习动作价值&quot;">​</a></h3><p>免模型控制通常估计 (Q(S_t,A_t))，让策略能比较同一状态下不同动作。若下一动作由当前行为策略实际选择，就得到 Sarsa 的同策略更新结构；若目标使用下一状态的最大动作价值，就走向 Q-learning 的异策略结构。</p><h3 id="_14-3-更新目标中的-下一项-决定算法身份" tabindex="-1">14.3 更新目标中的“下一项”决定算法身份 <a class="header-anchor" href="#_14-3-更新目标中的-下一项-决定算法身份" aria-label="Permalink to &quot;14.3 更新目标中的“下一项”决定算法身份&quot;">​</a></h3><p>TD 控制算法看起来只在目标里换了一个符号，但它决定正在评估哪种后续行为。下一篇会专门拆解 (S_t,A_t,R_{t+1},S_{t+1},A_{t+1}) 这组数据，解释 Sarsa 为什么把探索风险也计入自己学习的策略价值。</p><h2 id="十五、放进自动驾驶任务前必须补哪些安全边界" tabindex="-1">十五、放进自动驾驶任务前必须补哪些安全边界 <a class="header-anchor" href="#十五、放进自动驾驶任务前必须补哪些安全边界" aria-label="Permalink to &quot;十五、放进自动驾驶任务前必须补哪些安全边界&quot;">​</a></h2><h3 id="_15-1-每步更新不等于允许道路在线探索" tabindex="-1">15.1 每步更新不等于允许道路在线探索 <a class="header-anchor" href="#_15-1-每步更新不等于允许道路在线探索" aria-label="Permalink to &quot;15.1 每步更新不等于允许道路在线探索&quot;">​</a></h3><p>真实车辆能以高频率产生转移数据，不代表可以让学习策略实时修改控制行为。训练更新、影子评估、回放验证、封闭场地测试和部署审批必须分层。TD 的在线性质是算法能力，不是安全许可。</p><h3 id="_15-2-延迟奖励仍然需要信用分配设计" tabindex="-1">15.2 延迟奖励仍然需要信用分配设计 <a class="header-anchor" href="#_15-2-延迟奖励仍然需要信用分配设计" aria-label="Permalink to &quot;15.2 延迟奖励仍然需要信用分配设计&quot;">​</a></h3><p>一次不舒适变道可能在数秒后才暴露风险，路线决策的后果甚至更晚出现。TD(0) 会逐步传播价值，但稀疏终点奖励仍可能学习缓慢。奖励设计、多步回报和状态表示需要共同处理延迟反馈。</p><h3 id="_15-3-安全约束不能折叠成一个平均价值" tabindex="-1">15.3 安全约束不能折叠成一个平均价值 <a class="header-anchor" href="#_15-3-安全约束不能折叠成一个平均价值" aria-label="Permalink to &quot;15.3 安全约束不能折叠成一个平均价值&quot;">​</a></h3><p>平均回报上升不能证明碰撞率、越界率或最坏场景风险下降。Safety Shield（安全屏蔽器）、Control Barrier Function（控制屏障函数）、规则约束和独立监控器应作为可验证的安全机制，不能依赖 TD 误差自然学出硬约束。</p><h3 id="_15-4-日志分布与部署分布必须分别评估" tabindex="-1">15.4 日志分布与部署分布必须分别评估 <a class="header-anchor" href="#_15-4-日志分布与部署分布必须分别评估" aria-label="Permalink to &quot;15.4 日志分布与部署分布必须分别评估&quot;">​</a></h3><p>训练日志若主要来自温和驾驶，价值函数可能在激进交互和边缘天气中外推失真。应按场景切片报告误差、覆盖度、安全指标和最坏分位数表现，并通过独立数据集检查分布变化。</p><h2 id="十六、一个最小随机游走实验应该验证什么" tabindex="-1">十六、一个最小随机游走实验应该验证什么 <a class="header-anchor" href="#十六、一个最小随机游走实验应该验证什么" aria-label="Permalink to &quot;十六、一个最小随机游走实验应该验证什么&quot;">​</a></h2><h3 id="_16-1-环境要有可计算真值" tabindex="-1">16.1 环境要有可计算真值 <a class="header-anchor" href="#_16-1-环境要有可计算真值" aria-label="Permalink to &quot;16.1 环境要有可计算真值&quot;">​</a></h3><p>可以建立一条由若干非终止状态组成的链，智能体每次随机向左或向右移动，进入左终点得到零奖励，进入右终点得到一奖励。固定随机策略下，各状态真实价值可以解析计算，适合做误差参照。</p><h3 id="_16-2-实验要同时实现-td-与蒙特卡洛" tabindex="-1">16.2 实验要同时实现 TD 与蒙特卡洛 <a class="header-anchor" href="#_16-2-实验要同时实现-td-与蒙特卡洛" aria-label="Permalink to &quot;16.2 实验要同时实现 TD 与蒙特卡洛&quot;">​</a></h3><p>两种方法使用相同轨迹预算和初始化，分别更新价值。记录不同回合数下各状态估计，并计算相对真值的 Root Mean Squared Error（均方根误差）。比较必须在多随机种子上汇总，不能用某条曲线证明普遍优劣。</p><h3 id="_16-3-必须做短轨迹手算" tabindex="-1">16.3 必须做短轨迹手算 <a class="header-anchor" href="#_16-3-必须做短轨迹手算" aria-label="Permalink to &quot;16.3 必须做短轨迹手算&quot;">​</a></h3><p>构造一条已知 (S_t,R_{t+1},S_{t+1}) 和初始价值的短轨迹，手算 TD 目标、TD 误差与更新后价值。终止转移要单独验证后继价值为零，截断转移则验证是否按任务语义保留自举。</p><h3 id="_16-4-学习率敏感性不能省略" tabindex="-1">16.4 学习率敏感性不能省略 <a class="header-anchor" href="#_16-4-学习率敏感性不能省略" aria-label="Permalink to &quot;16.4 学习率敏感性不能省略&quot;">​</a></h3><p>至少比较几组 (\\alpha)，观察收敛速度和后期波动。若某个方法只在为自己精调的学习率上展示，而另一个方法沿用默认值，结论没有可比性。</p><h2 id="十七、实现时最常见的错误" tabindex="-1">十七、实现时最常见的错误 <a class="header-anchor" href="#十七、实现时最常见的错误" aria-label="Permalink to &quot;十七、实现时最常见的错误&quot;">​</a></h2><h3 id="_17-1-奖励和下一状态索引错位" tabindex="-1">17.1 奖励和下一状态索引错位 <a class="header-anchor" href="#_17-1-奖励和下一状态索引错位" aria-label="Permalink to &quot;17.1 奖励和下一状态索引错位&quot;">​</a></h3><p>从 (S_t) 采取动作后收到的是 (R_{t+1}) 和 (S_{t+1})。轨迹缓存或环境接口若错一位，公式形式仍能运行，却更新了错误因果关系。</p><h3 id="_17-2-更新顺序意外改变目标" tabindex="-1">17.2 更新顺序意外改变目标 <a class="header-anchor" href="#_17-2-更新顺序意外改变目标" aria-label="Permalink to &quot;17.2 更新顺序意外改变目标&quot;">​</a></h3><p>计算目标时应明确使用哪一版本的 (V(S_{t+1}))。在线原地更新、回合后批量更新和同步更新可能产生不同学习轨迹。实现与实验说明必须一致。</p><h3 id="_17-3-把-td-误差当成环境奖励记录" tabindex="-1">17.3 把 TD 误差当成环境奖励记录 <a class="header-anchor" href="#_17-3-把-td-误差当成环境奖励记录" aria-label="Permalink to &quot;17.3 把 TD 误差当成环境奖励记录&quot;">​</a></h3><p>奖励是任务信号，TD 误差是学习残差。两者应分字段记录。把误差混进奖励统计，会让奖励曲线和算法诊断都失去含义。</p><h3 id="_17-4-终止掩码把截断一起清零" tabindex="-1">17.4 终止掩码把截断一起清零 <a class="header-anchor" href="#_17-4-终止掩码把截断一起清零" aria-label="Permalink to &quot;17.4 终止掩码把截断一起清零&quot;">​</a></h3><p>许多环境同时返回终止和截断标志。若代码用一个合并后的 done（结束标志）统一屏蔽后继价值，时间上限附近可能产生偏差。必须根据任务是否真正终止决定目标。</p><h3 id="_17-5-只看训练回报-不看价值误差" tabindex="-1">17.5 只看训练回报，不看价值误差 <a class="header-anchor" href="#_17-5-只看训练回报-不看价值误差" aria-label="Permalink to &quot;17.5 只看训练回报，不看价值误差&quot;">​</a></h3><p>预测实验的目标是估计固定策略价值，训练回报主要由环境和策略决定，不会因为价值估计更准就必然上升。应使用可计算真值、TD 误差统计、状态访问计数和独立评估数据判断学习质量。</p><h2 id="十八、接下来进入-sarsa" tabindex="-1">十八、接下来进入 Sarsa <a class="header-anchor" href="#十八、接下来进入-sarsa" aria-label="Permalink to &quot;十八、接下来进入 Sarsa&quot;">​</a></h2><p>TD(0) 已经解决了“未知模型下如何逐步预测价值”，但控制还需要回答“怎样比较动作并改进策略”。把 (V(s)) 换成 (Q(s,a))，再把实际采取的下一动作纳入目标，就得到 Sarsa 的核心结构。</p><p>下一篇将解释 Sarsa 名字对应的五元组、同策略学习究竟“同”在哪里、(\\varepsilon)-贪心探索为什么会进入价值目标，以及它与 Q-learning 在悬崖行走任务中为何形成不同风险偏好。</p><h2 id="十九、参考资料" tabindex="-1">十九、参考资料 <a class="header-anchor" href="#十九、参考资料" aria-label="Permalink to &quot;十九、参考资料&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter3/chapter3.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第 3 章表格型方法源码</a></p><p><a href="https://web.stanford.edu/class/psych209/Readings/SuttonBartoIPRLBook2ndEd.pdf" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction（强化学习导论）》第 2 版全文</a></p><p><a href="https://mitpress.mit.edu/9780262039246/reinforcement-learning/" target="_blank" rel="noreferrer">MIT Press（麻省理工学院出版社）《Reinforcement Learning: An Introduction（强化学习导论）》第 2 版页面</a></p><p><a href="https://www.youtube.com/watch?v=PnHCvfgC_ZA" target="_blank" rel="noreferrer">Google DeepMind（谷歌深度思维）David Silver 强化学习课程第 4 讲</a></p><p>本文为强化学习入门系列第 06 篇。文中公式、示意图与自动驾驶案例均按教学目的重新组织，不构成真实车辆部署或安全论证。</p>',163)])])}const T=e(s,[["render",p]]);export{f as __pageData,T as default};
